function SpaghettiMap() {
  const sc = {};
  for (let i=0;i<LOGIST_PATH.length-1;i++){const a=LOGIST_PATH[i],b=LOGIST_PATH[i+1];const k=[Math.min(a.x,b.x),Math.min(a.y,b.y),Math.max(a.x,b.x),Math.max(a.y,b.y)].join(",");sc[k]=(sc[k]||0)+1;}
  const mx=Math.max(...Object.values(sc));
  return (
    <svg viewBox="0 0 560 270" style={{ width:"100%",height:"auto" }}>
      <rect x="10" y="10" width="540" height="250" rx="8" fill="#fafafa" stroke={s.border} />
      {LOGIST_PATH.slice(0,-1).map((p,i)=>{const nx=LOGIST_PATH[i+1];const k=[Math.min(p.x,nx.x),Math.min(p.y,nx.y),Math.max(p.x,nx.x),Math.max(p.y,nx.y)].join(",");const ct=sc[k]||1;const intensity=ct/mx;const g=Math.round(200-intensity*170);return <line key={i} x1={p.x} y1={p.y} x2={nx.x} y2={nx.y} stroke={`rgb(${g},${g},${g})`} strokeWidth={1+intensity*3} strokeLinecap="round" opacity={0.5+intensity*0.5}/>;
      })}
      {TABLE_POSITIONS.map(t=><g key={t.id}><rect x={t.x-18} y={t.y-14} width="36" height="28" rx="6" fill={s.white} stroke={s.border}/><text x={t.x} y={t.y+4} textAnchor="middle" fontSize="11" fontWeight="600" fill={s.textSec} fontFamily="Inter">{"№"+t.id}</text></g>)}
      <circle cx={LOGIST_PATH[0].x} cy={LOGIST_PATH[0].y} r="5" fill={s.green}/>
      <circle cx={LOGIST_PATH[LOGIST_PATH.length-1].x} cy={LOGIST_PATH[LOGIST_PATH.length-1].y} r="5" fill={s.text}/>
    </svg>
  );
}

