// VIDEO UPLOAD PAGE
// ═══════════════════════════════════════════════════════════════════

function VideoUploadPage({ videoData, onUpload }) {
  const fileRef = useRef(null);
  const [dragging, setDragging] = useState(false);
  const [processing, setProcessing] = useState(false);
  const [progress, setProgress] = useState(0);

  const handleFile = (file) => {
    if (!file) return;
    setProcessing(true);
    setProgress(0);

    // Animated progress bar, then mock data
    const steps = [
      { p: 15, t: 400 },
      { p: 35, t: 800 },
      { p: 60, t: 1300 },
      { p: 85, t: 1800 },
      { p: 100, t: 2200 },
    ];
    steps.forEach(({ p, t }) => setTimeout(() => setProgress(p), t));

    setTimeout(() => {
      onUpload({
        fileName: file.name,
        duration: 16,
        framesAnalyzed: 8,
        violations: [
          { id: 1, operator: "Оператор 3", time: "00:04", type: "Каскетка", desc: "Не обнаружена при сборке", frameIdx: 0 },
          { id: 2, operator: "Оператор 7", time: "00:11", type: "Перчатки", desc: "Отсутствуют при работе", frameIdx: 1 },
        ],
        complianceRate: 75,
        operatorsTotal: 8,
        operatorsOk: 6,
      });
      setProcessing(false);
      setProgress(0);
    }, 2500);
  };

  if (processing) {
    return (
      <div style={{ padding:"24px 32px 60px",maxWidth:1100,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",minHeight:400 }}>
        <div style={{ width:48,height:48,border:"4px solid "+s.border,borderTopColor:s.accent,borderRadius:"50%",animation:"spin 1s linear infinite" }} />
        <style>{"@keyframes spin { to { transform: rotate(360deg); } }"}</style>
        <div style={{ fontSize:15,fontWeight:600,marginTop:20 }}>Анализ видео...</div>
        <div style={{ fontSize:13,color:s.textTer,marginTop:8,marginBottom:20 }}>CV-пайплайн извлекает кадры и детектирует СИЗ</div>
        <div style={{ width:300,height:6,borderRadius:3,backgroundColor:s.borderLight,overflow:"hidden" }}>
          <div style={{ height:"100%",borderRadius:3,backgroundColor:s.accent,width:progress+"%",transition:"width 0.4s ease" }} />
        </div>
        <div style={{ fontSize:11,color:s.textTer,marginTop:8 }}>{progress}%</div>
      </div>
    );
  }

  if (videoData) {
    return (
      <div style={{ padding:"24px 32px 60px",maxWidth:1100 }}>
        <div style={{ display:"flex",gap:12,marginBottom:16 }}>
          <Card style={{ padding:"18px 22px",flex:1 }}>
            <div style={{ fontSize:11,color:s.textTer,fontWeight:500,textTransform:"uppercase",letterSpacing:"0.04em",marginBottom:8 }}>Нарушения СИЗ</div>
            <div style={{ fontSize:32,fontWeight:700,color:s.red,lineHeight:1 }}>{videoData.violations.length}</div>
          </Card>
          <Card style={{ padding:"18px 22px",flex:1 }}>
            <div style={{ fontSize:11,color:s.textTer,fontWeight:500,textTransform:"uppercase",letterSpacing:"0.04em",marginBottom:8 }}>Кадров проанализировано</div>
            <div style={{ fontSize:32,fontWeight:700,lineHeight:1 }}>{videoData.framesAnalyzed}</div>
          </Card>
          <Card style={{ padding:"18px 22px",flex:1 }}>
            <div style={{ fontSize:11,color:s.textTer,fontWeight:500,textTransform:"uppercase",letterSpacing:"0.04em",marginBottom:8 }}>Соответствие СИЗ</div>
            <div style={{ fontSize:32,fontWeight:700,color:s.green,lineHeight:1 }}>{videoData.complianceRate}%</div>
          </Card>
          <Card style={{ padding:"18px 22px",flex:1 }}>
            <div style={{ fontSize:11,color:s.textTer,fontWeight:500,textTransform:"uppercase",letterSpacing:"0.04em",marginBottom:8 }}>Файл</div>
            <div style={{ fontSize:14,fontWeight:600,lineHeight:1.3,wordBreak:"break-all" }}>{videoData.fileName}</div>
            <div style={{ fontSize:11,color:s.textTer,marginTop:4 }}>{videoData.duration} сек</div>
          </Card>
        </div>
        <Card style={{ padding:"20px 22px",marginBottom:16 }}>
          <div style={{ fontSize:13,fontWeight:600,marginBottom:14 }}>Обнаруженные нарушения</div>
          <table style={{ width:"100%",borderCollapse:"collapse",fontSize:13,fontFamily:font }}>
            <thead><tr>{["#","Оператор","Время","Тип СИЗ","Описание"].map((h,i)=><TH key={i}>{h}</TH>)}</tr></thead>
            <tbody>{videoData.violations.map(v=>(
              <tr key={v.id} style={{ borderBottom:`1px solid ${s.borderLight}` }}>
                <td style={{ padding:"11px 14px",fontWeight:500 }}>{v.id}</td>
                <td style={{ padding:"11px 14px",fontWeight:500 }}>{v.operator}</td>
                <td style={{ padding:"11px 14px",color:s.textSec }}>{v.time}</td>
                <td style={{ padding:"11px 14px" }}>{v.type}</td>
                <td style={{ padding:"11px 14px",color:s.textSec }}>{v.desc}</td>
              </tr>))}</tbody>
          </table>
        </Card>
        <Card style={{ padding:"20px 22px",marginBottom:16 }}>
          <div style={{ fontSize:13,fontWeight:600,marginBottom:10 }}>Операторы без нарушений</div>
          <div style={{ display:"flex",flexWrap:"wrap",gap:8 }}>
            {Array.from({length:videoData.operatorsOk||6},(_,i)=>(
              <span key={i} style={{ padding:"6px 14px",borderRadius:20,fontSize:12,fontWeight:500,backgroundColor:s.greenBg,color:s.green,border:"1px solid #bbf7d0" }}>{"Оператор "+(i+1)}</span>
            ))}
          </div>
        </Card>
        <div style={{ marginTop:16,textAlign:"center" }}>
          <button onClick={()=>{onUpload(null);}} style={{ padding:"10px 20px",borderRadius:10,border:`1px solid ${s.border}`,backgroundColor:s.white,fontSize:13,fontWeight:500,cursor:"pointer",fontFamily:font,color:s.textSec }}>↻ Загрузить другое видео</button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ padding:"24px 32px 60px",maxWidth:1100 }}>
      <div
        onDragOver={e=>{e.preventDefault();setDragging(true);}}
        onDragLeave={()=>setDragging(false)}
        onDrop={e=>{e.preventDefault();setDragging(false);if(e.dataTransfer.files[0]) handleFile(e.dataTransfer.files[0]);}}
        onClick={()=>{if(fileRef.current) fileRef.current.click();}}
        style={{
          border:`2px dashed ${dragging?s.blue:s.border}`,borderRadius:16,padding:"80px 40px",
          textAlign:"center",cursor:"pointer",backgroundColor:dragging?s.blueBg:s.white,
          transition:"all 0.2s",
        }}
      >
        <div style={{ fontSize:48,marginBottom:16 }}>🎬</div>
        <div style={{ fontSize:16,fontWeight:600,marginBottom:8 }}>Загрузите видео для анализа</div>
        <div style={{ fontSize:13,color:s.textTer,marginBottom:20,maxWidth:400,margin:"0 auto 20px" }}>
          Перетащите видеофайл сюда или нажмите для выбора. CV-пайплайн извлечёт кадры и проанализирует наличие СИЗ.
        </div>
        <div style={{ display:"inline-flex",alignItems:"center",gap:6,padding:"10px 24px",borderRadius:10,backgroundColor:s.accent,color:s.accentText,fontSize:13,fontWeight:600 }}>
          📁 Выбрать видео
        </div>
        <div style={{ fontSize:11,color:s.textTer,marginTop:12 }}>MP4, MOV, AVI · до 500 МБ</div>
      </div>
      <input ref={fileRef} type="file" accept="video/*" style={{ display:"none" }} onChange={e=>{ if(e.target.files[0]) handleFile(e.target.files[0]); }} />
    </div>
  );
}

